  ctx.fillStyle = '#FFE08A'; for (let k = 0; k < 16; k++) { const a = a0 + k * Math.PI / 8; ell(ctx, X + Math.cos(a) * R2, Y + Math.sin(a) * R2, 4 * u, 4 * u); ctx.fill(); }
