  for (const bx of G.L.boxes) if (bx.strain > 0.5) { msg = G.mode === 'solo' ? '一个人推不动！先「牵手」，再一起推' : '一个人推不动，要两个人一起推！'; at = [bx.x + 1, bx.y - 0.3]; }
