  const [a, b] = G.players;
  if (G.hold) G.hold = false;
  else if (!a.dead && !b.dead && Math.abs(a.x - b.x) < 1.9 && Math.abs(a.y - b.y) < 1.2) { G.hold = true; sfx('swap'); }
  else { const p = G.players[G.active]; G.hint = { text: '走到对方旁边才能牵手', at: [p.x + p.w / 2, p.y - 0.3], t: G.clock + 1.6 }; }
